function f = HS47_f(x)
f = (x(1) - x(2)).^2 + (x(2) - x(3)).^3 + (x(3) - x(4)).^4 + (x(4) - x(5)).^4;
end

function g = HS47_g(x)
g = zeros(5, 1);
g(1) = 2*x(1) - 2*x(2);
g(2) = -2*x(1) + 2*x(2) + 3*(x(2) - x(3)).^2;
g(3) = -3*(x(2) - x(3)).^2 + 4*(x(3) - x(4)).^3;
g(4) = -4*(x(3) - x(4)).^3 + 4*(x(4) - x(5)).^3;
g(5) = -4*(x(4) - x(5)).^3;
end

function c = HS47_c(x)
c = zeros(3, 1);
c(1) = x(1) + x(2).^2 + x(3).^3 - 3;
c(2) = x(2) - x(3).^2 + x(4) - 1;
c(3) = x(1).*x(5) - 1;
end

function J = HS47_J(x)
J = zeros(3, 5);
J(1, 1) = 1;
J(1, 2) = 2*x(2);
J(1, 3) = 3*x(3).^2;
J(2, 2) = 1;
J(2, 3) = -2*x(3);
J(2, 4) = 1;
J(3, 1) = x(5);
J(3, 5) = x(1);
end
